'use strict';

// Checks the macOS service files generated by deploy/mac/traitors.sh.
// (launchctl itself only exists on a Mac, so this covers the generated config.)

const test = require('node:test');
const assert = require('node:assert/strict');
const { execFileSync } = require('child_process');
const path = require('path');

const script = path.join(__dirname, '..', 'deploy', 'mac', 'traitors.sh');
let hasBash = process.platform !== 'win32';
try {
  execFileSync('bash', ['-c', 'true']);
} catch {
  hasBash = false;
}

test('mac setup script generates valid service definitions', { skip: !hasBash && 'bash not available' }, () => {
  execFileSync('bash', ['-n', script]);
  const out = execFileSync('bash', [script, 'print-plists', '/opt/homebrew/bin/node', '4321', 'a&b<c>"d'], { encoding: 'utf8' });
  const docs = out.split('<?xml').slice(1);
  assert.equal(docs.length, 2);
  const [server, tunnel] = docs;
  for (const doc of docs) {
    // Every tag that opens is closed; no raw special characters inside strings.
    for (const m of doc.matchAll(/<string>([^<]*)<\/string>/g)) assert.ok(!/[<>"]|&(?!amp;|lt;|gt;|quot;)/.test(m[1]), m[1]);
    assert.equal((doc.match(/<dict>/g) || []).length, (doc.match(/<\/dict>/g) || []).length);
    assert.match(doc, /<key>KeepAlive<\/key><true\/>/);
    assert.match(doc, /<key>RunAtLoad<\/key><true\/>/);
  }
  assert.match(server, /<string>com\.traitors\.server<\/string>/);
  assert.match(server, /<string>\/opt\/homebrew\/bin\/node<\/string>/);
  assert.match(server, /<key>PORT<\/key><string>4321<\/string>/);
  assert.match(server, /<key>TRAITORS_ADMIN_PASSWORD<\/key><string>a&amp;b&lt;c&gt;&quot;d<\/string>/);
  assert.match(tunnel, /<string>com\.traitors\.tunnel<\/string>/);
  assert.match(tunnel, /<string>http:\/\/127\.0\.0\.1:4321<\/string>/, 'tunnel points at IPv4 loopback on the same port');
  // Without a password, none is written (the server generates and saves one).
  const noPw = execFileSync('bash', [script, 'print-plists', '/usr/bin/node', '3000'], { encoding: 'utf8' });
  assert.ok(!noPw.includes('TRAITORS_ADMIN_PASSWORD'));
});
